import{At as e,Pt as t,Ut as n,gt as r,ht as i,n as a,pt as o,ut as s}from"./chunks/framework.BrKcMR_c.js";var c=JSON.parse(`{"title":"ADR-0081: Owner-prepared automatic uninstall","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0081-owner-prepared-automatic-uninstall.md","filePath":"adrs/0081-owner-prepared-automatic-uninstall.md","lastUpdated":1789092097000}`),l={name:`adrs/0081-owner-prepared-automatic-uninstall.md`};function u(a,c,l,u,d,f){let p=t(`Term`);return e(),o(`div`,null,[c[25]||=s(`h1`,{id:`adr-0081-owner-prepared-automatic-uninstall`,tabindex:`-1`},[i(`ADR-0081: Owner-prepared automatic uninstall `),s(`a`,{class:`header-anchor`,href:`#adr-0081-owner-prepared-automatic-uninstall`,"aria-label":`Permalink to “ADR-0081: Owner-prepared automatic uninstall”`},`​`)],-1),c[26]||=s(`p`,null,`Status: Accepted`,-1),c[27]||=s(`p`,null,`Date: 2026-09-10`,-1),c[28]||=s(`h2`,{id:`context`,tabindex:`-1`},[i(`Context `),s(`a`,{class:`header-anchor`,href:`#context`,"aria-label":`Permalink to “Context”`},`​`)],-1),s(`p`,null,[c[1]||=i(`The owner requested automatic app removal with independent choices to keep macOS preferences, connections, `,-1),r(p,{term:`pen`},{default:n(()=>[...c[0]||=[i(`Pens`,-1)]]),_:1}),c[2]||=i(`, local memory, customisations and chats. A shell command that removes a running app and live database cannot preserve those choices reliably. The review-only Settings prototype also repeated the same parent paths and truncated its entry button.`,-1)]),c[29]||=s(`h2`,{id:`decision`,tabindex:`-1`},[i(`Decision `),s(`a`,{class:`header-anchor`,href:`#decision`,"aria-label":`Permalink to “Decision”`},`​`)],-1),s(`p`,null,[c[4]||=i(`Settings displays a storage tree and an uninstall review with Partial uninstall selected by default. This keeps GOAT Home data and chats/attachments while selecting macOS preferences/window state for removal. Uninstall all checks every removal option; selecting Partial uninstall restores the default selection. Checkboxes select removal: checked items are removed and unchecked items are kept. Individual removal options remain editable, and retaining any category returns the mode to Partial uninstall. Entering the uninstall tab starts with the partial default. The separate local-data removal preview is removed; category choices live in uninstall, alongside direct preference reset (`,-1),c[5]||=s(`a`,{href:`/adrs/0082-direct-preference-reset`},`ADR-0082`,-1),c[6]||=i(`). Removing Pen metadata also selects chats and attachments; keeping chats preserves Pen metadata. External workspaces, referenced project files, model `,-1),r(p,{term:`engine`},{default:n(()=>[...c[3]||=[i(`engines`,-1)]]),_:1}),c[7]||=i(` and remote memory are excluded. Only this app copy and an explicitly selected, signature-checked `,-1),c[8]||=s(`code`,null,`goat`,-1),c[9]||=i(` CLI can be removed.`,-1)]),s(`p`,null,[c[11]||=i(`The review is the final confirmation: an `,-1),c[12]||=s(`strong`,null,`Are you sure?`,-1),c[13]||=i(` page lists what will be removed, what will be kept, the recovery folder and the requirement to quit normally. Its `,-1),c[14]||=s(`strong`,null,`Uninstall`,-1),c[15]||=i(` button has no additional dialog. After that explicit confirmation, the app copies its complete signed application bundle into an owner-only temporary directory, verifies the copied signature, and launches the copied executable in its fixed `,-1),c[16]||=s(`code`,null,`--goat-uninstall-helper`,-1),c[17]||=i(` mode with a private typed request. The entry point dispatches this mode before creating AppModel or opening storage. There is no shell, privileged helper, launch agent, arbitrary command or network operation. The complete copy retains the Info.plist and sealed resources bound by Developer ID signing; a naked executable copy fails macOS signature validation even when an ad-hoc fixture succeeds. The helper validates its exact executable and bundle paths inside the private job; the `,-1),r(p,{term:`judas`},{default:n(()=>[...c[10]||=[i(`JUDAS`,-1)]]),_:1}),c[18]||=i(` source check allows only this reviewed local process-launch site.`,-1)]),s(`p`,null,[c[20]||=i(`The helper waits for its exact launching process to exit. Preparation checks startup, active turns, queued Lead, `,-1),r(p,{term:`goated`},{default:n(()=>[...c[19]||=[i(`extension`,-1)]]),_:1}),c[21]||=i(` changes and pending approvals. It does not terminate GOAT or claim to drain every view-owned task. The owner must finish imports, commands and other work and then quit normally. A prepared request can be cancelled while GOAT is open and expires after one hour. This deliberately avoids forcing shutdown during active work.`,-1)]),c[30]||=s(`p`,null,`Normal launches hold a per-user shared maintenance lock before any app state is created. After the parent exits, the helper takes that lock exclusively and refuses cleanup if another GOAT copy is running. New versions cannot open storage during cleanup. Older releases do not implement this lock; visible older copies are checked, and users must not launch an old version during maintenance.`,-1),s(`p`,null,[c[23]||=i(`The helper validates captured root identities and builds a fresh inventory after process exit. It uses recognised config filenames and Pen metadata files, and selected memory, skills, `,-1),r(p,{term:`theme`},{default:n(()=>[...c[22]||=[i(`themes`,-1)]]),_:1}),c[24]||=i(`, extensions and attachment categories. It never moves shared roots, follows symbolic links, removes unknown top-level entries or traverses an external workspace. Selected data moves into a private recovery directory using same-volume renames, with a planned manifest and a completed-move journal. Cross-volume recovery destinations are rejected before any source move. Empty directories and linked entries remain in place.`,-1)]),c[31]||=s(`p`,null,`When requested, preferences are backed up as a private plist and cleared through the macOS preferences API after exit. Saved window state is handled separately from the home and database. App and CLI copies move to macOS Trash after data handling. Failures stop further moves and leave a recovery report. The helper removes its private bundle/request directory when it finishes; it never removes the recovery folder.`,-1),c[32]||=s(`h2`,{id:`consequences-and-validation`,tabindex:`-1`},[i(`Consequences and validation `),s(`a`,{class:`header-anchor`,href:`#consequences-and-validation`,"aria-label":`Permalink to “Consequences and validation”`},`​`)],-1),c[33]||=s(`p`,null,`Automatic uninstall is recoverable, not secure erasure. Recovery can contain credentials and conversations, and restoring it requires a compatible app version, closed storage and review before overwriting files. A custom home remains recorded in the recovery request even when preferences are removed. Retained Pen memory remains in its original folders when Pen metadata is removed.`,-1),c[34]||=s(`p`,null,`Tests cover retained categories, linked targets, unknown files, nested workspaces, live-host refusal, changed roots, database companions, preference-domain isolation and partial recovery. Native review checks cover storage grouping, keep selections, confirmation and the Settings entry layout. Helper process checks use disposable fixtures; they must never uninstall the maintainer's active app. Release qualification must verify the copied signed executable under the final notarized distribution identity before publishing this functionality.`,-1)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};